                # So we'll use the same logic as the original but without is_admin parameter
                # We'll create a generic error message since we don't have is_admin info
                error_msg = f"Error cancelling order. Please try again later. Reference code: {ref_code}"
            else:
                error_msg = f"Error cancelling order. Please try again later. Reference code: {ref_code}"

            return (500, error_msg)
